import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  // specs/hal-engine-tool-input-validation/spec.md#1
  it('returns the missing required property without invoking the executor', async () => {
    const registry = new ToolRegistry();
    let calls = 0;
    registry.register(
      {name: 'weather', description: 'Weather', inputSchema: {type: 'object', required: ['location']}},
      async () => {
        calls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('weather', {});

    expect(response.result).toMatch(/location.*required|required.*location/i);
    expect(calls).toBe(0);
  });
});
EOF
